// Monta UMA mensagem POR DONO agregando tarefas due
const tarefasAll = items.filter(i => i.json && i.json.titulo);
if (!tarefasAll.length) return [];

const porDono = {};
for (const t of tarefasAll) { (porDono[t.json.dono_numero] ||= []).push(t.json); }

const out = [];
const allIds = [];
for (const [dono, tarefas] of Object.entries(porDono)) {
  const tz = tarefas[0].timezone || 'America/Sao_Paulo';
  const horaLocal = parseInt(new Date().toLocaleString('sv-SE', { timeZone: tz }).substring(11,13), 10);
  let saudacao = horaLocal < 12 ? 'Bom dia' : (horaLocal < 18 ? 'Boa tarde' : 'Boa noite');

  const atrasadas = tarefas.filter(t => t.urgencia === 'atrasada');
  const hoje = tarefas.filter(t => t.urgencia === 'hoje');
  const outras = tarefas.filter(t => t.urgencia === 'normal');

  let partes = [];
  if (atrasadas.length) partes.push('Atrasadas (passou do prazo):\n' + atrasadas.slice(0,5).map(t => `- #${t.id} ${t.titulo}`).join('\n') + (atrasadas.length > 5 ? `\n...e mais ${atrasadas.length-5}` : ''));
  if (hoje.length) partes.push('Pra hoje:\n' + hoje.slice(0,5).map(t => `- #${t.id} ${t.titulo}`).join('\n') + (hoje.length > 5 ? `\n...e mais ${hoje.length-5}` : ''));
  if (outras.length) partes.push((atrasadas.length || hoje.length ? 'Outras pendentes:' : 'Pendentes:') + '\n' + outras.slice(0,5).map(t => `- #${t.id} ${t.titulo}`).join('\n') + (outras.length > 5 ? `\n...e mais ${outras.length-5}` : ''));

  let abertura;
  if (atrasadas.length) abertura = `${saudacao}, oh, tem ${atrasadas.length} tarefa${atrasadas.length>1?'s':''} atrasada${atrasadas.length>1?'s':''}.`;
  else if (hoje.length) abertura = `${saudacao}. Hoje tem ${hoje.length} pra fazer.`;
  else abertura = `${saudacao}, te lembrando das pendentes.`;

  const fechamento = tarefas.length === 1
    ? '\n\nJa fez? Manda "feito" se ja resolveu ou "adia" pra empurrar.'
    : '\n\nPra dar baixa: "fiz a ' + tarefas[0].id + '", "fiz a X e a Y" ou "fiz todas". Pra empurrar: "adia a X". Audio tambem vale.';

  // tarefa cobrada 6+ vezes sem resposta: avisa que vai parar de insistir (e passa a cobrar a cada 3 dias)
  const cansadas = tarefas.filter(t => Number(t.cobranca_count || 0) >= 6);
  const avisoCansadas = cansadas.length
    ? '\n\nEssa' + (cansadas.length > 1 ? 's eu ja cobrei' : ' eu ja cobrei') + ' varias vezes: ' + cansadas.slice(0, 4).map(t => '#' + t.id).join(', ') +
      '. Se nao vai rolar, manda "cancela a ' + cansadas[0].id + '" que eu paro de lembrar.'
    : '';
  const texto = abertura + '\n\n' + partes.join('\n\n') + fechamento + avisoCansadas;
  const ids = tarefas.map(t => t.id);
  allIds.push(...ids);
  out.push({ json: { send_to: dono, send_text: texto } });
}

// SQL unico pra atualizar todas cobradas
const idsUrgentes = [], idsNormais = [], idsCansadas = [];
for (const [dono, tarefas] of Object.entries(porDono)) {
  for (const t of tarefas) {
    if (Number(t.cobranca_count || 0) >= 6) idsCansadas.push(t.id);           // ja insistiu demais: a cada 3 dias
    else (t.urgencia === 'normal' ? idsNormais : idsUrgentes).push(t.id);
  }
}
const upds = [];
if (idsUrgentes.length) upds.push(`UPDATE giulia_tarefas SET ultima_cobranca_em = NOW(), cobranca_count = cobranca_count + 1, proxima_cobranca_em = NOW() + INTERVAL '8 hours' WHERE id IN (${idsUrgentes.join(',')});`);
if (idsNormais.length) upds.push(`UPDATE giulia_tarefas SET ultima_cobranca_em = NOW(), cobranca_count = cobranca_count + 1, proxima_cobranca_em = NOW() + INTERVAL '24 hours' WHERE id IN (${idsNormais.join(',')});`);
if (idsCansadas.length) upds.push(`UPDATE giulia_tarefas SET ultima_cobranca_em = NOW(), cobranca_count = cobranca_count + 1, proxima_cobranca_em = NOW() + INTERVAL '72 hours' WHERE id IN (${idsCansadas.join(',')});`);
const sqlUpdate = upds.join('\n') || 'SELECT 1;';
out.forEach(o => o.json.sql_update = sqlUpdate);
return out;
